nta.declaration:
// WashiOS payload-link supervision, timed-automata model.
// Source of constants: core/include/comms/PayloadLinkController.hpp,
// core/src/app/PayloadLinkTask.hpp, demo-payload/src/main.cpp.
// Time unit: 1 ms.

const int POLL_MS      = 500;   // PayloadLinkController::PollPeriodMs
const int DEADLINE_MS  = 100;   // PayloadLinkController::ResponseTimeoutMs
const int OFFLINE_N    = 3;     // PayloadLinkController::OfflineThreshold
const int LOOP_MS      = 1;     // PayloadLinkTask::LoopPeriodMs (service quantum)
const int JITTER_MS    = 2;     // RTOS wakeup + ISR jitter bound per loop pass (assumption A1)

// DRAFT-CAMERA-READY (2026-10-18). Assumption A2 is re-derived as a ROUND TRIP measured from the
// controller's poll stamp (preparePoll(nowMs) precedes the blocking write), integer-rounded outward:
//   request decoded by the responder  in [DECODE_MIN, DECODE_MAX] after the poll stamp
//     = 32-byte poll at 115200 8N1 (2.78 ms) + rest of the responder loop pass (HAL_Delay(1): up to 2 ms)
//       + at most one blocking debug line written earlier in the same pass (longest MODE line,
//       39 bytes = 3.39 ms) + decode work;
//   response fully received at the controller in [RESP_MIN, RESP_MAX] after the decode
//     = encode + 32-byte response (2.78 ms);
//   DELAYED adds HAL_Delay(d), which waits between d and d + DELAY_EXTRA ms;
//   the controller consumes a received frame at its next loop pass, within LOOP + JITTER.
// The payload mode is captured at DECODE time (handleRequest reads currentMode), not at the poll.
const int DECODE_MIN_MS  = 2;
const int DECODE_MAX_MS  = 9;
const int RESP_MIN_MS    = 2;
const int RESP_MAX_MS    = 4;
const int DELAY_EXTRA_MS = 1;

// DRAFT-CAMERA-READY. Status-report slip (assumption A7, evidence-derived, host-observed): the poll
// schedule slips by up to SLIP_MS once per PAYLOAD_STATUS report (StatusPeriodMs = 5000). The frozen
// 605 s nominal observation shows a slip of 10..54.5 ms (n = 241) at each status report and none
// elsewhere; the cause is not established. Modelled as one block of the link task of at most SLIP_MS
// per STATUS_PERIOD_MS, during which it neither polls, nor evaluates the deadline, nor consumes a frame
// (the USART1 ISR still buffers bytes). 0 is patched by tooling/run_verifyta.sh:
// 0 (between status reports, Status template absent) or 60.
const int STATUS_PERIOD_MS = 5000;
const int SLIP_MS          = 0;

// Payload behaviors (comms::PayloadMode ordering: Normal=0, Silent=1, BadCrc=2, Delayed=3)
const int NORMAL  = 0;
const int SILENT  = 1;
const int BAD_CRC = 2;
const int DELAYED = 3;

// Configured DELAYED response time. Instantiated per verification run by
// tooling/run_verifyta.sh (50, 90, 100, 110, 150, 250). Default is the demo value.
const int DELAY_MS = 90;

// Fault exposure and recovery observation windows used by the frozen campaign
// (run_payload_campaign.py --observe-s 4.0 --recovery-observe-s 3.0).
const int EXPOSURE_MS = 4000;
const int RECOVERY_MS = 3000;

// Link state (comms::PayloadLinkState)
const int STARTING = 0;
const int ONLINE   = 1;
const int OFFLINE  = 2;

// Channels
chan poll;          // controller -> payload, poll stamped and sent (preparePoll nowMs)
chan resp_ok;       // payload -> controller, valid frame fully received
chan resp_badcrc;   // payload -> controller, CRC-corrupted frame fully received
broadcast chan inject, restore;

// Verified bounds (used by the queries). Every bound is INCLUSIVE: the event happens no later
// than the bound, so the queries test 'clock > BOUND' and the tightness queries show that
// 'clock >= BOUND' is not sufficient. JITTER appears once per poll period because nextPollMs is
// anchored at the actual send instant, so jitter accumulates. A confirmed mode change can at the
// earliest follow the decode of the previous poll, DECODE_MIN after its stamp, hence '- DECODE_MIN'.
// At most one status block (SLIP) falls inside any of these windows (all shorter than STATUS_PERIOD_MS).
const int FIRST_TIMEOUT_BOUND_MS = POLL_MS + JITTER_MS - DECODE_MIN_MS + DEADLINE_MS + LOOP_MS + JITTER_MS + SLIP_MS;               // 603 (+SLIP)
const int OFFLINE_BOUND_MS       = OFFLINE_N * (POLL_MS + JITTER_MS) - DECODE_MIN_MS + DEADLINE_MS + LOOP_MS + JITTER_MS + SLIP_MS;  // 1607 (+SLIP)
const int RECOVERY_BOUND_MS      = POLL_MS + JITTER_MS - DECODE_MIN_MS + DECODE_MAX_MS + RESP_MAX_MS + LOOP_MS + JITTER_MS + SLIP_MS; // 516 (+SLIP)
const int LATE_FRAME_BOUND_MS    = POLL_MS + JITTER_MS + SLIP_MS + DECODE_MAX_MS + DELAY_MS + DELAY_EXTRA_MS + RESP_MAX_MS;

// Delay-acceptance boundary under assumptions A1, A2, A7:
//   ACCEPTS   : the latest possible response still precedes the earliest deadline check
//               (a status block delays the deadline check and the frame pickup alike, and the
//               frame is received before the deadline is serviced, so SLIP does not enter);
//   TIMES_OUT : the earliest possible response follows the latest deadline check (SLIP enters).
//   Neither   : undetermined band (86..99 ms with SLIP 0; 86..159 ms with SLIP 60).
const bool ACCEPTS   = DELAY_MS + DECODE_MAX_MS + DELAY_EXTRA_MS + RESP_MAX_MS < DEADLINE_MS;
const bool TIMES_OUT = DELAY_MS + DECODE_MIN_MS + RESP_MIN_MS > DEADLINE_MS + LOOP_MS + JITTER_MS + SLIP_MS;

// Shared observable state (bounded, saturating; mirrors the parts of PayloadLinkStats
// and the log markers that the properties need)
int[0,2]   link = STARTING;
int[0,3]   consecutive = 0;        // saturates at OFFLINE_N (code saturates at 255; only the threshold matters)

// Per-exposure observables, reset by Host on inject/restore
int[0,3]   toutInFault = 0;        // saturating count of timeouts since injection
bool       crcInFault = false;     // a CRC reject occurred since injection
bool       seqInFault = false;     // a sequence reject occurred since injection
bool       offlineInFault = false;
bool       recoveredAfterRestore = false;

int[0,3]   mode = NORMAL;

// Status-report block (assumption A7)
bool       blocked = false;        // link task blocked by the status report
int[0,SLIP_MS] slack = 0;          // extra allowance for the controller's next action after a block

template.declaration:
clock xPoll;   // time since last poll was stamped
clock xResp;   // time since the outstanding poll was stamped
clock xk;      // time since the response frame was fully received (pickup)
bool awaiting = false;

void onTimeout() {
    awaiting = false;
    if (toutInFault < 3) toutInFault++;
    if (consecutive < OFFLINE_N) consecutive++;
    if (consecutive >= OFFLINE_N) { link = OFFLINE; offlineInFault = true; }
}

void onAccept() {
    bool wasOffline = (link == OFFLINE);
    awaiting = false;
    consecutive = 0;
    link = ONLINE;
    if (wasOffline) { recoveredAfterRestore = true; }
}

nta.system:
// One trial: nominal warm-up, one fault exposure of FAULT_MODE, restoration.
// FAULT_MODE is patched by tooling/run_verifyta.sh for SILENT, BAD_CRC, DELAYED.
//  is patched to ", St" (status block present) or "" (between status reports).
H = Host(DELAYED);
C = Controller();
P = Payload();
St = Status();
system C, P, H ;
